(function(){
 'use strict';
 const {disasters,portal,assess,matchKeywords}=SafetyCore;
 const q=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const get=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
 function put(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{q('#hubStatus').textContent='브라우저 저장 공간을 사용할 수 없습니다. 설정은 현재 화면에서만 유지됩니다.';return false}}
 let selected='fire',answers=get('sk-survey',{}),custom=get('sk-conditions',{}),prefs=get('sk-alert-prefs',{name:'',email:'',keywords:['산사태','폭우','계엄령','전쟁'],push:true,emailOn:true,consent:false}),inbox=get('sk-inbox',[]),lastMatch=null;
 if(!Array.isArray(prefs.keywords))prefs.keywords=[];
 q('#safetyHub').innerHTML=`<section id="disasters" class="section disaster-section"><div class="section-head"><div><div class="eyebrow">02 / DISASTER RESPONSE</div><h2>상황이 다르면, 대피 방법도 다르게.</h2></div><span class="demo-tag">재난별 행동 가이드</span></div><p class="hub-intro">평소의 위험 조건과 비상시 행동을 함께 확인하세요. 지금 위험한 상황이라면 설문보다 안전 확보와 119 신고가 먼저입니다.</p><div id="hazardTabs" class="hazard-tabs" role="tablist" aria-label="재난 종류">${disasters.map(d=>`<button id="tab-${d.id}" role="tab" aria-controls="hazardPanel" aria-selected="${d.id===selected}" tabindex="${d.id===selected?0:-1}" data-hazard="${d.id}"><span>${d.icon}</span>${d.name}</button>`).join('')}</div><div id="hazardPanel" role="tabpanel" aria-labelledby="tab-fire"></div></section>
 <section id="survey" class="section survey-section"><div class="section-head"><div><div class="eyebrow">03 / WHAT IS HAPPENING NOW?</div><h2>지금 상황을 골라 주세요.</h2></div><span id="surveyBadge" class="demo-tag"></span></div><div class="survey-layout"><aside><span class="large-index">PICK<br><em>YOUR<br>SITUATION.</em></span><p>현재와 가장 가까운 상황에서 <b>“예, 지금 그래요”</b>를 고르면 바로 행동 요령을 보여드려요.</p><p class="source">현재 위험하다면 이 화면을 읽느라 지체하지 말고 우선 안전한 곳으로 이동해 119에 신고하세요. 답변은 이 브라우저에만 저장됩니다.</p><a href="#disasters" class="text-link">다른 재난 상황 선택 ↑</a></aside><div><form id="surveyForm"><div id="questions"></div><button class="button" type="submit">내 상황의 행동 요령 모아보기 ↗</button><button id="resetSurvey" type="button" class="hub-outline">선택 초기화</button></form><details class="custom-condition"><summary>＋ 나만의 상황 메모 추가</summary><form id="conditionForm"><label>상황이나 질문<input name="condition" required maxlength="100" placeholder="예: 일행과 떨어졌고 휴대전화가 안 터지나요?"></label><label>이 상황에서 할 일<input name="action" required maxlength="180" placeholder="예: 현재 위치를 알리고 사람이 많은 안전한 장소에서 기다리기"></label><p class="source">직접 추가한 항목은 개인 메모입니다. 공식 안전 안내를 대신하지 않습니다.</p><button class="button" type="submit">상황 메모 추가</button></form></details><div id="surveyResult" aria-live="polite"></div></div></div></section>
 <section id="alerts" class="section alert-section"><div class="section-head"><div><div class="eyebrow">04 / KEYWORD WATCH</div><h2>관심 키워드에서, 필요한 행동까지.</h2></div><span class="demo-tag">알림 흐름 시연</span></div><div class="connection-note"><span class="status-dot"></span><div><b>뉴스 자동 수집 · 회원 서버 · 웹 푸시 · 이메일 발송 미연결</b><p>아래는 설정 저장과 예시 기사 감지를 체험하는 초안입니다. 실제 뉴스를 감시하거나 회원에게 자동 발송하지 않습니다.</p></div></div><div class="alert-layout"><div class="alert-settings"><div class="panel-title"><span>01</span><h3>회원 알림 사전설정</h3></div><form id="prefsForm"><div class="two-inputs"><label>표시 이름<input name="name" maxlength="30" placeholder="예: 세이프킷 회원"></label><label>이메일 주소<input name="email" type="email" maxlength="254" placeholder="you@example.com" autocomplete="email"></label></div><p class="source">실제 회원가입·이메일 인증은 진행되지 않습니다. 입력 정보는 서버로 전송되지 않고 이 브라우저에만 저장됩니다.</p><label class="field-label">관심 키워드</label><div id="keywordChips" class="keyword-chips"></div><div class="keyword-add"><input id="keywordInput" maxlength="30" aria-label="추가할 관심 키워드" placeholder="키워드 직접 입력"><button id="addKeyword" type="button" class="hub-outline">추가</button></div><div class="suggested">추천 <button type="button" data-keyword="화재">＋ 화재</button><button type="button" data-keyword="지진">＋ 지진</button><button type="button" data-keyword="침수">＋ 침수</button></div><fieldset class="channel-options"><legend>수신 채널 사전선택</legend><label><input name="push" type="checkbox"> 웹 푸시</label><label><input name="emailOn" type="checkbox"> 이메일</label></fieldset><label class="consent-line"><input name="consent" type="checkbox" required><span>시연용 입력 정보를 이 브라우저에 저장하는 데 동의합니다.</span></label><div class="form-actions"><button class="button" type="submit">사전설정 저장 ↗</button><button class="hub-outline" id="deletePrefs" type="button">저장 정보 삭제</button></div><p id="prefsStatus" class="inline-status" role="status"></p></form></div><div class="alert-demo"><div class="panel-title"><span>02</span><h3>뉴스 키워드 감지 체험</h3></div><p class="source">실제 뉴스가 아닌 가상 제목을 넣어 매칭과 알림함을 확인합니다. 제목에 단어가 있다는 것만으로 발생을 확인하지 않습니다.</p><form id="newsForm"><label>가상 기사 제목<textarea id="newsTitle" required maxlength="300" rows="3">[시연] 집중호우 대비 산사태 취약지역 점검 안내</textarea></label><div class="sample-buttons"><button type="button" data-sample="rain">폭우·산사태 예시</button><button type="button" data-sample="war">전쟁·계엄 예시</button><button type="button" data-sample="none">일치 없음 예시</button></div><button class="button" type="submit">키워드 감지 시연 ↗</button></form><p id="detectStatus" class="inline-status" role="status"></p><div class="delivery-previews"><button type="button" id="previewPush" class="hub-outline">브라우저 알림 시연</button><button type="button" id="previewEmail" class="hub-outline">이메일 내용 미리보기</button></div><p class="source">브라우저 알림은 권한을 허용한 이 기기에서 버튼을 눌렀을 때만 표시합니다. 백그라운드 웹 푸시와 이메일 발송은 연결 전입니다.</p><div id="deliveryStatus" class="inline-status" role="status"></div><div id="emailPreview" hidden></div></div></div><div class="inbox-head"><div><h3>알림함 <span id="inboxCount">0</span></h3><p>모든 항목은 가상 기사로 만든 시연 알림입니다.</p></div><button type="button" id="clearInbox" class="hub-outline">알림 비우기</button></div><div id="alertInbox"></div><p id="hubStatus" class="inline-status" role="status"></p></section>`;
 function current(){return disasters.find(d=>d.id===selected)}
 function allQuestions(){return [...current().questions,...(custom[selected]||[])]}
 function warManuals(){return `<section class="war-manuals" aria-labelledby="warManualTitle"><div class="war-title"><div><span class="step-label red">SITUATION / DETAILED PLAYBOOK</span><h4 id="warManualTitle">${esc(current().name)} 상황별 행동 매뉴얼</h4><p>상황을 고르면 순서대로 해야 할 일과 준비물을 확인할 수 있어요.</p></div><span class="war-count">${current().manuals.length}개 상황</span></div><div class="war-layout"><nav class="war-tabs" role="tablist" aria-label="${esc(current().name)} 상황별 행동 매뉴얼">${current().manuals.map((m,i)=>`<button type="button" role="tab" id="war-tab-${m.id}" aria-controls="warManualPanel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-war-manual="${m.id}"><span aria-hidden="true">${m.icon}</span><span>${esc(m.title)}</span><b aria-hidden="true">›</b></button>`).join('')}</nav><div class="war-content"><div id="warMotion" class="war-motion" aria-hidden="true"><div class="motion-scene"><span class="motion-window"></span><span class="motion-door"></span><span class="motion-floor"></span><svg class="motion-person" viewBox="0 0 100 150" role="presentation"><circle cx="50" cy="19" r="12"/><path d="M38 37 Q50 30 62 37 L67 78 Q50 85 33 78Z"/><path d="M38 42 L22 66 M62 42 L78 66 M39 78 L32 117 M61 78 L69 117"/><path d="M32 117 L22 140 M69 117 L79 140"/><path class="person-bag" d="M32 43 Q25 42 25 53 L24 69"/></svg><span class="motion-target" aria-hidden="true">⬇</span></div><span class="motion-label">짧은 동작 시연 · 실제 촬영 영상이 아닌 안내용 애니메이션</span></div><div id="warManualPanel" class="manual-detail" role="tabpanel" aria-labelledby="war-tab-home"></div></div></div><p class="war-source">재난별 행동 안내는 아래의 공식 원문 링크를 확인하세요. 추가 참고: <a href="https://www.safekorea.go.kr/safekorea-kor/acts/nacts/action-guide.do?actsHeaderTitle=비상대비&category=stateOfEmergency&menuSn=4" target="_blank" rel="noopener">국민안전24 비상대비</a> · <a href="https://safekorea.go.kr/safekorea-kor/acts/nacts/action-guide.do?actsHeaderTitle=민방공경보&category=civlAirDefenseWarning&menuSn=4" target="_blank" rel="noopener">민방공경보</a> · <a href="https://www.safekorea.go.kr/safekorea-kor/acts/nacts/action-guide.do?actsHeaderTitle=화생방무기&category=chemicalandBiologicalWeapons&menuSn=4" target="_blank" rel="noopener">화생방·핵·방사능 낙진</a> · <a href="https://www.cdc.gov/radiation-emergencies/response/get-inside.html" target="_blank" rel="noopener">CDC 실내 대피·오염 제거</a>. 지시가 서로 다르면 현재 재난문자와 현장 통제를 따르세요.</p></section>`}
 function renderManual(id){
  const d=current(),m=d.manuals.find(x=>x.id===id)||d.manuals[0],panel=q('#warManualPanel');
  document.querySelectorAll('[data-war-manual]').forEach(b=>{const active=b.dataset.warManual===m.id;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});
  panel.setAttribute('aria-labelledby','war-tab-'+m.id);
  panel.innerHTML=`<div class="manual-heading"><span class="manual-icon" aria-hidden="true">${m.icon}</span><div><span class="step-label red">${esc(m.source||d.source)}</span><h5>${esc(m.title)}</h5></div></div><p class="manual-lead">${esc(m.lead)}</p><ol class="manual-steps">${m.steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(s)}</p></li>`).join('')}</ol>${m.timeline?`<div class="nuclear-timeline"><h6>⏱️ 낙진 이후 시간별로 기억하기</h6>${m.timeline.map(t=>`<div><b>${esc(t[0])}</b><p>${esc(t[1])}</p></div>`).join('')}</div>`:''}${m.recommendations?`<section class="manual-recommendations"><h6>🎒 이 상황에서 준비하면 좋은 물품</h6><div>${m.recommendations.map(r=>`<a href="https://www.coupang.com/np/search?q=${encodeURIComponent(r[1])}" target="_blank" rel="noopener noreferrer">${esc(r[0])} · 쿠팡에서 찾기 ↗</a>`).join('')}</div><p>쿠팡 검색 결과로 이동합니다. 상품 가격·재고와 상세 정보는 쿠팡에서 확인하세요.</p></section>`:''}<div class="manual-avoid"><b>🚫 하지 말 것</b><p>${esc(m.avoid)}</p></div><div class="manual-controls"><button type="button" class="hub-outline" data-manual-prev>← 이전 상황</button><span>${d.manuals.findIndex(x=>x.id===m.id)+1} / ${d.manuals.length}</span><button type="button" class="hub-outline" data-manual-next>다음 상황 →</button></div>`;
  q('#warMotion').dataset.scene=m.id;q('#warMotion').className='war-motion scene-'+m.id
 } function wireManuals(){const tabs=q('#hazardPanel');tabs.onclick=e=>{const b=e.target.closest('[data-war-manual]');if(b){renderManual(b.dataset.warManual);return}const step=e.target.closest('[data-manual-prev],[data-manual-next]');if(!step)return;const manuals=current().manuals,i=manuals.findIndex(m=>m.id===q('#warMotion').dataset.scene),next=step.hasAttribute('data-manual-next')?(i+1)%manuals.length:(i-1+manuals.length)%manuals.length;renderManual(manuals[next].id)};tabs.onkeydown=e=>{const b=e.target.closest('[data-war-manual]');if(!b||!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const items=current().manuals,i=items.findIndex(m=>m.id===b.dataset.warManual),next=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;renderManual(items[next].id);q('#war-tab-'+items[next].id).focus()};renderManual(current().manuals[0].id)}
 function renderHazard(){const d=current();q('#hazardPanel').setAttribute('aria-labelledby','tab-'+d.id);q('#hazardPanel').innerHTML=`<div class="hazard-overview"><div><span class="eyebrow">${d.icon} ${esc(d.name)} / RESPONSE GUIDE</span><h3>${esc(d.summary)}</h3><div class="condition-tags">${d.conditions.map(c=>`<span>${esc(c)}</span>`).join('')}</div></div><a href="#survey" class="button">이 상황의 조건 점검 ↘</a></div>${d.manuals?warManuals():''}<div class="response-grid"><article><span class="step-label">BEFORE / 평소에</span><h4>미리 준비하기</h4><ul>${d.before.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article><article><span class="step-label red">DURING / 발생 시</span><h4>행동·대피 요령</h4><ol>${d.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article></div><div class="avoid-note"><b>주의할 행동</b><p>${esc(d.avoid)}</p></div><div class="hazard-source"><span>참고: ${esc(d.source)} · 확인일 2026.11.12</span><a href="${d.url}" target="_blank" rel="noopener">공식 원문 확인 ↗</a></div><p class="source">일반적인 대비 안내입니다. 실제 대응은 현장 상태, 건물별 피난 계획, 관계 기관의 안내를 따르세요.</p>`;if(d.manuals)wireManuals();renderQuestions();q('#surveyResult').innerHTML=''}
 function selectHazard(id){selected=id;document.querySelectorAll('[data-hazard]').forEach(b=>{const active=b.dataset.hazard===id;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});renderHazard()}
 q('#hazardTabs').onclick=e=>{const b=e.target.closest('[data-hazard]');if(b)selectHazard(b.dataset.hazard)};
 q('#hazardTabs').onkeydown=e=>{const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();let i=disasters.findIndex(d=>d.id===selected);i=e.key==='Home'?0:e.key==='End'?disasters.length-1:(i+(e.key==='ArrowRight'?1:-1)+disasters.length)%disasters.length;selectHazard(disasters[i].id);q('#tab-'+selected).focus()};
 function renderQuestions(){q('#surveyBadge').textContent=current().name+' 상황 안내';const values=answers[selected]||{};q('#questions').innerHTML=`<p class="scenario-intro">해당하는 상황을 골라 보세요. 선택하면 바로 “지금 할 일”이 나타납니다.</p>`+allQuestions().map(item=>`<fieldset class="survey-question"><legend>${esc(item[1])}${item[0].startsWith('custom-')?'<small>내 상황 메모</small>':''}</legend><div class="answer-options">${[['yes','예, 지금 그래요'],['no','아니요']].map(([v,t])=>`<label><input type="radio" name="${item[0]}" value="${v}" ${values[item[0]]===v?'checked':''}><span>${t}</span></label>`).join('')}${item[0].startsWith('custom-')?`<button type="button" data-remove-condition="${item[0]}" aria-label="직접 추가한 조건 삭제">삭제</button>`:''}</div>${values[item[0]]==='yes'?`<div class="live-action"><b>✅ 지금 할 일</b><p>${esc(Array.isArray(item[2])?item[2][0]:item[2])}</p><b>⛔ 하지 말 것</b><p>${esc(Array.isArray(item[2])?item[2][1]:'안전한 곳으로 이동해 도움을 요청하세요.')}</p></div>`:''}</fieldset>`).join('')}
 q('#surveyForm').onchange=e=>{if(!e.target.matches('input[type=radio]'))return;answers[selected]??={};answers[selected][e.target.name]=e.target.value;put('sk-survey',answers);renderQuestions();q('#surveyResult').innerHTML=''};
 q('#surveyForm').onsubmit=e=>{e.preventDefault();const d=current(),selectedNow=allQuestions().filter(x=>answers[selected]?.[x[0]]==='yes');if(!selectedNow.length){q('#surveyResult').innerHTML='<div class="survey-result"><h3>해당하는 상황을 선택해 주세요.</h3><p>아래 상황을 고르면 해야 할 일과 피할 일을 바로 알려드려요.</p></div>';return}q('#surveyResult').innerHTML=`<div class="survey-result"><div class="eyebrow">🚨 ${esc(d.name)} / 지금 할 일</div><h3>${selectedNow.length}개 상황의 행동 안내</h3><p>안전하게 이동할 수 없다면 119에 위치와 인원을 알리세요.</p>${selectedNow.map(x=>`<article class="action-card"><h4>${esc(x[1])}</h4><b>✅ 지금 할 일</b><p>${esc(Array.isArray(x[2])?x[2][0]:x[2])}</p><b>⛔ 하지 말 것</b><p>${esc(Array.isArray(x[2])?x[2][1]:'위험을 무릅쓰지 말고 119에 도움을 요청하세요.')}</p></article>`).join('')}<a href="#disasters" class="text-link">${esc(d.name)} 전체 행동 안내 보기 ↑</a></div>`;q('#surveyResult').scrollIntoView({behavior:'smooth',block:'nearest'})};
 q('#resetSurvey').onclick=()=>{answers[selected]={};put('sk-survey',answers);renderQuestions();q('#surveyResult').innerHTML='<p class="inline-status">이 재난의 답변을 초기화했습니다.</p>'};
 q('#conditionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),text=String(f.get('condition')).trim(),action=String(f.get('action')).trim();if(!text||!action)return;custom[selected]??=[];if(custom[selected].length>=8){toast('재난별 직접 추가 항목은 8개까지 가능합니다');return}custom[selected].push(['custom-'+crypto.randomUUID(),text,action]);put('sk-conditions',custom);e.target.reset();renderQuestions();q('#surveyResult').innerHTML='';toast('선택한 재난에 조건을 추가했습니다')};
 q('#questions').onclick=e=>{let b=e.target.closest('[data-remove-condition]');if(!b)return;custom[selected]=custom[selected].filter(x=>x[0]!==b.dataset.removeCondition);if(answers[selected])delete answers[selected][b.dataset.removeCondition];put('sk-conditions',custom);put('sk-survey',answers);renderQuestions();q('#surveyResult').innerHTML=''};renderHazard();
 const pf=q('#prefsForm');function fillPrefs(){pf.elements.name.value=prefs.name||'';pf.elements.email.value=prefs.email||'';pf.elements.push.checked=!!prefs.push;pf.elements.emailOn.checked=!!prefs.emailOn;pf.elements.consent.checked=!!prefs.consent;renderKeywords()}
 function renderKeywords(){q('#keywordChips').innerHTML=prefs.keywords.length?prefs.keywords.map((k,i)=>`<span>${esc(k)}<button type="button" data-remove-keyword="${i}" aria-label="${esc(k)} 키워드 삭제">×</button></span>`).join(''):'<p class="source">관심 키워드를 추가해 주세요.</p>'}
 function addKeyword(k){k=k.normalize('NFKC').trim();if(!k)return;if(k.length>30||prefs.keywords.length>=12){toast('키워드는 30자, 최대 12개까지 가능합니다');return}if(prefs.keywords.some(x=>x.toLowerCase()===k.toLowerCase())){toast('이미 추가한 키워드입니다');return}prefs.keywords.push(k);renderKeywords();q('#keywordInput').value='';q('#prefsStatus').textContent='키워드가 변경되었습니다. 사전설정 저장을 눌러 주세요.'}
 q('#addKeyword').onclick=()=>addKeyword(q('#keywordInput').value);q('#keywordInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addKeyword(e.target.value)}};q('#keywordChips').onclick=e=>{let b=e.target.closest('[data-remove-keyword]');if(!b)return;prefs.keywords.splice(+b.dataset.removeKeyword,1);renderKeywords();q('#prefsStatus').textContent='키워드가 변경되었습니다. 사전설정 저장을 눌러 주세요.'};document.querySelectorAll('[data-keyword]').forEach(b=>b.onclick=()=>addKeyword(b.dataset.keyword));fillPrefs();
 pf.onsubmit=e=>{e.preventDefault();if(!prefs.keywords.length){q('#prefsStatus').textContent='관심 키워드를 1개 이상 선택해 주세요.';return}if(!pf.elements.push.checked&&!pf.elements.emailOn.checked){q('#prefsStatus').textContent='수신 채널을 1개 이상 선택해 주세요.';return}if(pf.elements.emailOn.checked&&!pf.elements.email.value.trim()){q('#prefsStatus').textContent='이메일 채널을 선택했다면 이메일 주소를 입력해 주세요.';return}prefs={...prefs,name:pf.elements.name.value.trim(),email:pf.elements.email.value.trim(),push:pf.elements.push.checked,emailOn:pf.elements.emailOn.checked,consent:pf.elements.consent.checked};if(put('sk-alert-prefs',prefs))q('#prefsStatus').textContent='이 브라우저에 사전설정을 저장했습니다. 실제 회원가입·발송은 진행되지 않았습니다.'};
 q('#deletePrefs').onclick=()=>{prefs={name:'',email:'',keywords:[],push:true,emailOn:true,consent:false};try{localStorage.removeItem('sk-alert-prefs');localStorage.removeItem('sk-inbox')}catch{}inbox=[];lastMatch=null;fillPrefs();renderInbox();q('#emailPreview').hidden=true;q('#deliveryStatus').textContent='';q('#detectStatus').textContent='';q('#prefsStatus').textContent='이 브라우저의 알림 설정·입력 정보·시연 알림을 삭제했습니다.'};
 const samples={rain:'[시연] 집중호우 대비 산사태 취약지역 점검 안내',war:'[시연] 전쟁·계엄령 관련 과거 보도 해설 — 현재 발생 소식 아님',none:'[시연] 지역 도서관 독서 프로그램 안내'};document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>{q('#newsTitle').value=samples[b.dataset.sample]});
 q('#newsForm').onsubmit=e=>{e.preventDefault();const title=q('#newsTitle').value.trim();if(!title)return;const matches=matchKeywords(title,prefs.keywords);lastMatch=null;q('#emailPreview').hidden=true;q('#deliveryStatus').textContent='';if(!matches.length){q('#detectStatus').textContent='일치하는 키워드가 없습니다. 알림을 만들지 않았습니다.';return}const existing=inbox.find(x=>x.title===title);if(existing){lastMatch=existing;q('#detectStatus').textContent='동일한 가상 제목은 중복 알림으로 추가하지 않았습니다. 기존 알림으로 채널 시연을 할 수 있습니다.';return}lastMatch={id:crypto.randomUUID(),title,keywords:matches,time:new Date().toISOString(),read:false};inbox.unshift(lastMatch);inbox=inbox.slice(0,30);put('sk-inbox',inbox);q('#detectStatus').textContent=matches.join(', ')+' 키워드 감지 · 시연 알림함에 추가했습니다. 발생이 확인된 경보가 아닙니다.';renderInbox()};
 function renderInbox(){q('#inboxCount').textContent=inbox.filter(x=>!x.read).length;q('#alertInbox').innerHTML=inbox.length?inbox.map(n=>`<article class="inbox-item ${n.read?'is-read':''}"><div class="inbox-symbol">♧</div><div><div class="inbox-meta"><span>시연 · 키워드 언급 감지</span><time datetime="${esc(n.time)}">${new Date(n.time).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})} KST</time></div><h4>${esc(n.title)}</h4><p>${n.keywords.map(esc).join(' · ')} <span> / 발생 여부 미확인</span></p><p class="source">제목의 단어 매칭입니다. 과거 기사·부정·가정 표현도 매칭될 수 있으므로 원문과 공식 발표를 확인해야 합니다.</p><a href="${portal}" target="_blank" rel="noopener">공식 안전정보 확인 ↗</a></div><button type="button" class="hub-outline" data-read-alert="${n.id}" ${n.read?'disabled':''}>${n.read?'읽음':'읽음 처리'}</button></article>`).join(''):'<div class="empty-inbox"><span>♧</span><h4>아직 감지한 시연 알림이 없습니다.</h4><p>관심 키워드를 고르고 가상 기사로 감지를 체험해 보세요.</p></div>'}
 q('#alertInbox').onclick=e=>{const b=e.target.closest('[data-read-alert]');if(!b)return;inbox=inbox.map(x=>x.id===b.dataset.readAlert?{...x,read:true}:x);put('sk-inbox',inbox);renderInbox()};q('#clearInbox').onclick=()=>{inbox=[];lastMatch=null;put('sk-inbox',inbox);renderInbox();q('#emailPreview').hidden=true;q('#deliveryStatus').textContent='';q('#detectStatus').textContent='시연 알림함을 비웠습니다.'};renderInbox();
 q('#previewPush').onclick=async()=>{const status=q('#deliveryStatus');if(!prefs.push){status.textContent='웹 푸시 채널을 먼저 선택하고 사전설정을 저장해 주세요.';return}if(!lastMatch){status.textContent='먼저 일치하는 가상 기사로 키워드 감지를 시연해 주세요.';return}if(!('Notification' in window)||!window.isSecureContext){status.textContent='이 브라우저에서는 알림을 지원하지 않습니다. 알림함에서 시연 내용을 확인하세요.';return}try{let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){status.textContent='브라우저 알림이 허용되지 않았습니다. 사이트 알림 권한을 확인하세요.';return}const n=new Notification('SAFEKIT · 시연 알림 / 발생 미확인',{body:lastMatch.title,tag:lastMatch.id});n.onclick=()=>{window.focus();q('#alertInbox').scrollIntoView({behavior:'smooth'});n.close()};status.textContent='이 기기에 브라우저 시연 알림을 표시했습니다. 자동 웹 푸시 구독은 생성하지 않았습니다.'}catch{status.textContent='이 환경에서는 직접 브라우저 알림을 표시할 수 없습니다. 알림함을 확인하세요.'}};
 q('#previewEmail').onclick=()=>{if(!prefs.emailOn){q('#deliveryStatus').textContent='이메일 채널을 먼저 선택하고 사전설정을 저장해 주세요.';return}if(!lastMatch){q('#deliveryStatus').textContent='먼저 일치하는 가상 기사로 키워드 감지를 시연해 주세요.';return}if(!pf.elements.email.checkValidity()||!pf.elements.email.value.trim()){q('#deliveryStatus').textContent='미리보기에 사용할 이메일 주소를 입력해 주세요.';return}q('#emailPreview').hidden=false;q('#emailPreview').innerHTML=`<div class="email-preview"><div class="eyebrow">EMAIL PREVIEW / 발송 안 됨</div><p>받는 사람: ${esc(pf.elements.email.value.trim())}</p><h4>[SAFEKIT 시연] 관심 키워드 언급 알림</h4><p>${esc(lastMatch.title)}</p><p>감지 키워드: ${lastMatch.keywords.map(esc).join(', ')}</p><p>이 예시는 재난 발생을 확인한 경보가 아닙니다. 실제 서비스에서는 기사 출처·게시 시각·원문 링크를 함께 제공합니다.</p></div>`;q('#deliveryStatus').textContent='이메일 내용을 미리 보여드립니다. 실제 이메일을 보내지 않았습니다.'};
})();
